import re

_UNIT_SECONDS = {
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
    "d": 86400, "day": 86400, "days": 86400,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
}

_UNIT_ALTS = "|".join(sorted(_UNIT_SECONDS.keys(), key=len, reverse=True))

_COMPONENT_RE = re.compile(
    r"(\d+(?:\.\d+)?)\s*(" + _UNIT_ALTS + r")", re.IGNORECASE
)

_FULL_COMPONENTS_RE = re.compile(
    r"^\s*(?:\d+(?:\.\d+)?\s*(?:" + _UNIT_ALTS + r")\s*)+$", re.IGNORECASE
)

_BARE_INT_RE = re.compile(r"^\d+$")

_CLOCK_RE = re.compile(r"^(\d+):(\d+)(?::(\d+))?$")

_ISO_RE = re.compile(
    r"^P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?"
    r"(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$",
    re.IGNORECASE,
)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty input")

    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # bare integer
    if _BARE_INT_RE.match(s):
        return int(s)

    # ISO 8601 duration
    m = _ISO_RE.match(s)
    if m and any(g is not None for g in m.groups()):
        weeks, days, hours, minutes, seconds = (
            float(g) if g is not None else 0.0 for g in m.groups()
        )
        total = (
            weeks * 604800
            + days * 86400
            + hours * 3600
            + minutes * 60
            + seconds
        )
        return round(total)

    # clock notation
    m = _CLOCK_RE.match(s)
    if m:
        parts = [p for p in m.groups() if p is not None]
        values = [int(p) for p in parts]
        if len(values) == 2:
            minutes, seconds = values
            return minutes * 60 + seconds
        elif len(values) == 3:
            hours, minutes, seconds = values
            return hours * 3600 + minutes * 60 + seconds

    # number+unit components
    if _FULL_COMPONENTS_RE.match(s):
        total = 0.0
        for value, unit in _COMPONENT_RE.findall(s):
            total += float(value) * _UNIT_SECONDS[unit.lower()]
        return round(total)

    raise ValueError(f"cannot parse duration: {text!r}")

